// .open-next/worker.js is generated by `npm run build:cloudflare`.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time
import { default as handler } from './.open-next/worker.js';
import { verifySessionTokenWithSecret, SESSION_COOKIE_NAME } from './lib/server-session';

function parseCookies(cookieHeader?: string | null): Record<string, string> {
  if (!cookieHeader) return {};
  return cookieHeader.split(';').reduce<Record<string, string>>((acc, part) => {
    const [name, ...value] = part.trim().split('=');
    if (!name) return acc;
    acc[name] = decodeURIComponent(value.join('='));
    return acc;
  }, {});
}

type OpenNextHandler = {
  fetch: (request: Request, env: WorkerEnv, context: WorkerExecutionContext) => Promise<Response> | Response;
};

type ScheduledControllerLike = {
  cron: string;
};

type D1PreparedLike = {
  bind: (...args: unknown[]) => D1PreparedLike;
  run: () => Promise<unknown>;
  first: () => Promise<unknown>;
  all: () => Promise<{ results?: unknown[] } | undefined>;
};

type WorkerEnv = Record<string, unknown> & {
  CRON_SECRET?: string;
  SESSION_SECRET?: string;
  DB?: {
    prepare: (sql: string) => D1PreparedLike;
    batch?: (statements: D1PreparedLike[]) => Promise<unknown>;
  };
  REALTIME_HUB?: {
    idFromName: (name: string) => unknown;
    get: (id: unknown) => { fetch: (req: Request) => Promise<Response> };
  };
};

type WorkerExecutionContext = {
  waitUntil?: (promise: Promise<unknown>) => void;
};

type CronRouteResult = {
  route: string;
  ok: boolean;
  status?: number;
  durationMs: number;
  bodyPreview?: string;
  error?: string;
};

const openNextHandler = handler as OpenNextHandler;

// wrangler.toml [triggers] crons 와 정확히 일치해야 한다.
// license-expiry-check 는 별도 cron 이 아니라 push-subscription-cleanup 끝에 통합 실행됨.
const CRON_ROUTES_BY_SCHEDULE: Record<string, string[]> = {
  // 5분 폴백 — 전송 직후 서버 즉시 디스패치가 실패해도 최대 ~5분 내 회수.
  // 월 호출 ≈ 12*24*30 = 8.6k (Workers 10M 한도의 0.1% 미만).
  '*/5 * * * *': ['/api/cron/chat-push-dispatch'],
  '0 15 * * *': ['/api/cron/backup'],
  // KST 02:00 — 채팅 보존정리 + 전날 결근 자동 생성.
  // 결근 생성은 원래 '30 15 * * *'(KST 00:30) 슬롯에 매핑돼 있었는데 wrangler [triggers] 에는
  // 그 표현식이 없어서 **한 번도 실행되지 않았다**. 크론 트리거 수를 늘리지 않고
  // 기존 슬롯에 얹는다 — 위 scheduled() 는 라우트를 순차 실행하며 개별 try/catch 로 격리한다.
  // 전날분 처리이므로 자정 직후 대신 02:00 이어도 결과는 같고, 늦은 퇴근 기록이 정리된 뒤라 오히려 안전하다.
  '0 17 * * *': ['/api/cron/chat-retention', '/api/cron/absent-auto-create'],
  '0 3 * * *': ['/api/cron/push-subscription-cleanup'],
  '0 0 * * *': [
    '/api/cron/unread-notification-repush',
    '/api/cron/leave-notice-announcements',
    '/api/cron/birthday-announcements',
    // 연차 자동화 (KST 09:00 매일):
    '/api/cron/annual-leave-accrual',
    '/api/cron/annual-leave-promotion',
    '/api/cron/annual-leave-expiry',
    '/api/cron/substitute-holiday',
    '/api/cron/payroll-notice',
    // 발령일이 도래한 예약 인사발령을 staff_members 에 반영.
    // (미래 발령은 등록 시 '대기' 로만 저장되므로 이 크론이 없으면 영원히 미반영으로 남는다.)
    '/api/cron/appointment-apply',
  ],
  // 구 /api/temp/resend · 일 1회 chat-push 슬롯 정리
  '0 4 * * *': [],
  // 레거시 wrangler 슬롯이 남아 있어도 no-op (배포 전 구 트리거 호환)
  '0 23 * * *': [],
};

function makeUuid() {
  return crypto.randomUUID();
}

/** cron 실행 결과를 audit_logs 에 남겨 대시보드/D1 로 추적 가능하게 한다. */
async function persistCronAudit(
  env: WorkerEnv,
  payload: {
    cron: string;
    route?: string;
    ok: boolean;
    durationMs: number;
    detail: Record<string, unknown>;
  },
) {
  const db = env.DB;
  if (!db?.prepare) return;

  const id = makeUuid();
  const nowIso = new Date().toISOString();
  const action = payload.ok ? 'cron_success' : 'cron_failure';
  const details = JSON.stringify({
    cron: payload.cron,
    route: payload.route || null,
    durationMs: payload.durationMs,
    ...payload.detail,
  });

  try {
    await db
      .prepare(
        `INSERT INTO audit_logs (id, user_id, user_name, action, target_type, target_id, details, actor_name, created_at)
         VALUES (?, NULL, 'system-cron', ?, 'cron', ?, ?, 'cron', ?)`,
      )
      .bind(id, action, payload.route || payload.cron, details, nowIso)
      .run();
  } catch (err) {
    console.error('[cron-audit] Failed to persist audit_logs:', err);
  }
}

/** 크론 실패 알림을 같은 라우트에 대해 다시 보내기까지 두는 간격. */
const CRON_ALERT_THROTTLE_HOURS = 6;

/**
 * 크론 실패를 관리자 알림함에 띄운다.
 *
 * audit_logs 에 남기는 것만으로는 아무도 모른다 — 2026-07-16 부터 12일간
 * CRON_SECRET 이 빈 값이라 백업·채팅푸시·연차자동화가 전부 멈췄는데
 * 실패 3,624건이 쌓이는 동안 알아챈 사람이 없었다. 실패는 사람에게 도달해야 한다.
 *
 * **의도적으로 env.DB 만 사용한다.** 알림을 Next 라우트 호출로 만들면
 * CRON_SECRET 이 비었을 때(=실제로 겪은 장애) 알림 자체도 같이 죽는다.
 * 알리려는 대상이 알림 경로를 망가뜨리는 상황이므로 경로를 공유해선 안 된다.
 */
async function notifyCronFailure(
  env: WorkerEnv,
  payload: { cron: string; route?: string; error: string },
) {
  const db = env.DB;
  if (!db?.prepare) return;

  const target = payload.route || payload.cron;
  const nowIso = new Date().toISOString();
  const throttleSinceIso = new Date(
    Date.now() - CRON_ALERT_THROTTLE_HOURS * 60 * 60 * 1000,
  ).toISOString();

  try {
    // 5분 크론이 실패하면 하루 288건이다. 라우트별로 간격을 두지 않으면
    // 알림함이 같은 실패로 도배돼 오히려 아무도 안 보게 된다.
    const recentAlert = await db
      .prepare(
        `SELECT id FROM audit_logs
         WHERE action = 'cron_failure_alert' AND target_id = ? AND created_at > ?
         LIMIT 1`,
      )
      .bind(target, throttleSinceIso)
      .first();
    if (recentAlert) return;

    // 관리자 판정은 claims.ts 의 기준과 맞춘다 (role admin/master 또는 이사·총무부장).
    const adminResult = await db
      .prepare(
        `SELECT id FROM staff_members
         WHERE status = '재직'
           AND (role IN ('admin', 'master') OR position IN ('이사', '총무부장'))`,
      )
      .all();
    const adminIds = ((adminResult?.results || []) as Array<{ id?: string }>)
      .map((row) => String(row?.id || '').trim())
      .filter(Boolean);
    if (adminIds.length === 0) return;

    const body = `${target} 실행이 실패했습니다. (${payload.error})`.slice(0, 500);
    const metadata = JSON.stringify({
      cron: payload.cron,
      route: payload.route || null,
      error: payload.error,
      action_required: true,
    });

    const statements = adminIds.map((adminId) =>
      db
        .prepare(
          `INSERT INTO notifications (id, user_id, type, title, body, metadata, created_at)
           VALUES (?, ?, 'system_alert', '크론 실행 실패', ?, ?, ?)`,
        )
        .bind(makeUuid(), adminId, body, metadata, nowIso),
    );

    // 알림 발송 이력 자체가 다음 알림의 스로틀 기준이 된다.
    statements.push(
      db
        .prepare(
          `INSERT INTO audit_logs (id, user_id, user_name, action, target_type, target_id, details, actor_name, created_at)
           VALUES (?, NULL, 'system-cron', 'cron_failure_alert', 'cron', ?, ?, 'cron', ?)`,
        )
        .bind(
          makeUuid(),
          target,
          JSON.stringify({ ...JSON.parse(metadata), notified: adminIds.length }),
          nowIso,
        ),
    );

    if (typeof db.batch === 'function') {
      await db.batch(statements);
    } else {
      for (const statement of statements) await statement.run();
    }
  } catch (err) {
    console.error('[cron-alert] Failed to notify admins:', err);
  }
}

async function callCronRoute(
  route: string,
  cron: string,
  env: WorkerEnv,
  context: WorkerExecutionContext,
): Promise<CronRouteResult> {
  const startTime = Date.now();
  const cronSecret = String(env.CRON_SECRET || '').trim();
  if (!cronSecret) {
    throw new Error('CRON_SECRET is not configured.');
  }

  const response = await openNextHandler.fetch(
    new Request(`https://worker-cron.local${route}`, {
      method: 'GET',
      headers: {
        authorization: `Bearer ${cronSecret}`,
        'x-cloudflare-cron': cron,
      },
    }),
    env,
    context,
  );

  const durationMs = Date.now() - startTime;
  const bodyText = await response.text().catch(() => '');
  const bodyPreview = bodyText.slice(0, 800);

  if (!response.ok) {
    throw Object.assign(
      new Error(`Cron route ${route} failed with ${response.status}: ${bodyPreview}`),
      { status: response.status, bodyPreview, durationMs },
    );
  }

  return {
    route,
    ok: true,
    status: response.status,
    durationMs,
    bodyPreview,
  };
}

const worker = {
  // OpenNext 가 생성한 fetch 핸들러로 위임 (this 바인딩 보존을 위해 래핑 호출).
  async fetch(request: Request, env: WorkerEnv, context: WorkerExecutionContext) {
    const url = new URL(request.url);
    if (url.pathname === '/api/realtime/ws') {
      if (request.headers.get('Upgrade') !== 'websocket') {
        return new Response('Expected Upgrade: websocket', { status: 426 });
      }

      const cookies = parseCookies(request.headers.get('Cookie'));
      const token = cookies[SESSION_COOKIE_NAME];
      const secret = String(env.SESSION_SECRET || 'dev-only-session-secret-change-this').trim();

      const session = await verifySessionTokenWithSecret(token, secret);
      if (!session || !session.user || !session.user.id) {
        return new Response('Unauthorized', { status: 401 });
      }

      const userId = String(session.user.id);
      const userName = String(session.user.name || '알 수 없음');

      const hub = env.REALTIME_HUB;
      if (!hub) {
        return new Response('REALTIME_HUB DurableObject binding not found', { status: 500 });
      }

      const doId = hub.idFromName('pchos-realtime-v1');
      const stub = hub.get(doId);

      const newHeaders = new Headers(request.headers);
      newHeaders.set('x-realtime-user-id', userId);
      newHeaders.set('x-realtime-user-name', userName);

      const doRequest = new Request(request, {
        headers: newHeaders,
      });

      return stub.fetch(doRequest);
    }
    return openNextHandler.fetch(request, env, context);
  },

  async scheduled(
    controller: ScheduledControllerLike,
    env: WorkerEnv,
    context: WorkerExecutionContext,
  ) {
    const routes = CRON_ROUTES_BY_SCHEDULE[controller.cron] || [];
    if (routes.length === 0) return;

    const batchStart = Date.now();
    const results: CronRouteResult[] = [];

    console.log(
      `[cron ${controller.cron}] Starting execution of ${routes.length} routes sequentially...`,
    );

    for (const route of routes) {
      const startTime = Date.now();
      try {
        console.log(`[cron ${controller.cron}] Starting route: ${route}`);
        const result = await callCronRoute(route, controller.cron, env, context);
        results.push(result);
        console.log(
          `[cron ${controller.cron}] Successfully finished route: ${route} (${result.durationMs}ms)`,
        );
        // 고비용 5분 cron 은 성공 시 스킵 — 실패만 기록 (audit_logs 폭주 방지)
        const isHighFrequency = controller.cron.startsWith('*/');
        if (!isHighFrequency) {
          context.waitUntil?.(
            persistCronAudit(env, {
              cron: controller.cron,
              route,
              ok: true,
              durationMs: result.durationMs,
              detail: { status: result.status, bodyPreview: result.bodyPreview },
            }),
          );
        }
      } catch (err) {
        const duration = Date.now() - startTime;
        const message = err instanceof Error ? err.message : String(err);
        const bodyPreview =
          err && typeof err === 'object' && 'bodyPreview' in err
            ? String((err as { bodyPreview?: string }).bodyPreview || '')
            : '';
        results.push({
          route,
          ok: false,
          durationMs: duration,
          error: message,
          bodyPreview,
        });
        console.error(
          `[cron ${controller.cron}] Route ${route} failed after ${duration}ms:`,
          err,
        );
        // 실패는 5분 cron 포함 항상 audit_logs 기록
        context.waitUntil?.(
          persistCronAudit(env, {
            cron: controller.cron,
            route,
            ok: false,
            durationMs: duration,
            detail: { error: message, bodyPreview },
          }),
        );
        // 기록만으로는 아무도 모른다 — 관리자 알림함까지 띄운다.
        context.waitUntil?.(
          notifyCronFailure(env, { cron: controller.cron, route, error: message }),
        );
      }
    }

    const failed = results.filter((r) => !r.ok);
    const batchDuration = Date.now() - batchStart;
    console.log(
      `[cron ${controller.cron}] Finished all routes. ok=${results.length - failed.length}/${results.length} (${batchDuration}ms)`,
    );

    // 일 단위 배치 요약 (고빈도 cron 제외)
    if (!controller.cron.startsWith('*/')) {
      context.waitUntil?.(
        persistCronAudit(env, {
          cron: controller.cron,
          ok: failed.length === 0,
          durationMs: batchDuration,
          detail: {
            summary: true,
            total: results.length,
            failed: failed.length,
            routes: results.map((r) => ({
              route: r.route,
              ok: r.ok,
              durationMs: r.durationMs,
              error: r.error || null,
            })),
          },
        }),
      );
    }
  },
};

export { RealtimeHub } from './lib/realtime/realtime-hub';
export default worker;
